python -c "
import numpy as np,itertools
L=open('answer.xyz').read().split('\n')
nat=int(L[0]); sym=[];pos=[]
for l in L[2:2+nat]:
    p=l.split(); sym.append(p[0]); pos.append([float(x) for x in p[1:4]])
pos=np.array(pos)
rad={'H':0.35,'C':0.77,'N':0.72,'P':1.10,'Os':1.4}
bonds={i:[] for i in range(nat)}
for i,j in itertools.combinations(range(nat),2):
    dd=np.linalg.norm(pos[i]-pos[j])
    if dd< 1.25*(rad[sym[i]]+rad[sym[j]]):
        bonds[i].append(j); bonds[j].append(i)
for i in range(nat):
    print(i,sym[i],len(bonds[i]),[(j,sym[j]) for j in bonds[i]] if sym[i]!='H' else '')
"
